import { useState, useMemo } from "react";
import { Trophy, Shield, Calendar, Star, Lock, LogOut, ChevronDown, ChevronUp, Menu, X } from "lucide-react";

// ─── CONSTANTS ───────────────────────────────────────────────────────────────
const ADMIN_PASSWORD = "tournament2026";

const LIME = "#BFFF00";
const MAGENTA = "#FF00AA";
const GOLD = "#FFD700";

// ─── TEAMS ───────────────────────────────────────────────────────────────────
const INITIAL_TEAMS = {
  A: ["Uzbekistan", "Portugal", "Mexico", "Cabo Verde"],
  B: ["Argentina", "Thailand", "Ecuador", "Colombia"],
  C: ["Brazil", "El Salvador", "Kazakhstan", "Angola"],
  D: ["Iraq", "USA", "Cuba", "TBD"],
};

// Generate all round-robin pairs for a bracket
function genRR(teams) {
  const matches = [];
  let id = 1;
  for (let i = 0; i < teams.length; i++) {
    for (let j = i + 1; j < teams.length; j++) {
      matches.push({ id: id++, t1: teams[i], t2: teams[j], s1: null, s2: null });
    }
  }
  return matches;
}

function initRR() {
  const rr = {};
  for (const br of ["A", "B", "C", "D"]) rr[br] = genRR(INITIAL_TEAMS[br]);
  return rr;
}

// ─── STANDINGS CALCULATOR ────────────────────────────────────────────────────
function calcStandings(matches, teams) {
  const table = {};
  for (const t of teams) table[t] = { w: 0, d: 0, l: 0, gf: 0, ga: 0, pts: 0 };

  for (const m of matches) {
    if (m.s1 === null || m.s2 === null) continue;
    const s1 = parseInt(m.s1), s2 = parseInt(m.s2);
    table[m.t1].gf += s1; table[m.t1].ga += s2;
    table[m.t2].gf += s2; table[m.t2].ga += s1;
    if (s1 > s2) { table[m.t1].w++; table[m.t1].pts += 3; table[m.t2].l++; }
    else if (s2 > s1) { table[m.t2].w++; table[m.t2].pts += 3; table[m.t1].l++; }
    else { table[m.t1].d++; table[m.t1].pts++; table[m.t2].d++; table[m.t2].pts++; }
  }

  return teams
    .map(t => ({ name: t, ...table[t], gd: table[t].gf - table[t].ga }))
    .sort((a, b) => b.pts - a.pts || b.gd - a.gd || b.gf - a.gf || a.name.localeCompare(b.name));
}

// ─── PLAYOFF SCHEDULE from image ─────────────────────────────────────────────
// QF1: Winner A vs Runner-Up B  (8:00 AM Field 1)
// QF2: Winner B vs Runner-Up A  (8:00 AM Field 2)
// QF3: Winner C vs Runner-Up D  (9:00 AM Field 1)
// QF4: Winner D vs Runner-Up C  (9:00 AM Field 2)
// SF1: Winner QF1 vs Winner QF3 (10:30 AM Field 1)
// SF2: Winner QF2 vs Winner QF4 (10:30 AM Field 2)
// FINAL: Winner SF1 vs Winner SF2 (12:00 PM Field 1)

function initPlayoffs() {
  return {
    qf: [
      { id: "qf1", label: "QF 1", time: "8:00 AM", field: "Field 1", t1: null, t2: null, t1key: "winA", t2key: "runB", s1: null, s2: null },
      { id: "qf2", label: "QF 2", time: "8:00 AM", field: "Field 2", t1: null, t2: null, t1key: "winB", t2key: "runA", s1: null, s2: null },
      { id: "qf3", label: "QF 3", time: "9:00 AM", field: "Field 1", t1: null, t2: null, t1key: "winC", t2key: "runD", s1: null, s2: null },
      { id: "qf4", label: "QF 4", time: "9:00 AM", field: "Field 2", t1: null, t2: null, t1key: "winD", t2key: "runC", s1: null, s2: null },
    ],
    sf: [
      { id: "sf1", label: "Semi-Final 1", time: "10:30 AM", field: "Field 1", t1: null, t2: null, s1: null, s2: null },
      { id: "sf2", label: "Semi-Final 2", time: "10:30 AM", field: "Field 2", t1: null, t2: null, s1: null, s2: null },
    ],
    final: [
      { id: "final", label: "Final", time: "12:00 PM", field: "Field 1", t1: null, t2: null, s1: null, s2: null },
    ],
  };
}

function getMatchWinner(m) {
  if (m.s1 === null || m.s2 === null) return null;
  const s1 = parseInt(m.s1), s2 = parseInt(m.s2);
  if (s1 > s2) return m.t1;
  if (s2 > s1) return m.t2;
  return null; // draw — shouldn't happen in playoffs
}

// ─── MAIN APP ─────────────────────────────────────────────────────────────────
export default function TournamentApp() {
  const [tab, setTab] = useState("group"); // group | playoffs | standings | scorers
  const [isAdmin, setIsAdmin] = useState(false);
  const [pwInput, setPwInput] = useState("");
  const [showLogin, setShowLogin] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);
  const [rrMatches, setRrMatches] = useState(initRR);
  const [playoffs, setPlayoffs] = useState(initPlayoffs);
  const [players, setPlayers] = useState({}); // { name: { team, goals } }
  const [editingMatch, setEditingMatch] = useState(null);
  const [scoreInputs, setScoreInputs] = useState({ s1: "", s2: "" });
  const [expandedBracket, setExpandedBracket] = useState("A");
  const [newPlayer, setNewPlayer] = useState({ name: "", team: "", goals: "" });
  const [showAddPlayer, setShowAddPlayer] = useState(false);

  // ── Standings derived ──
  const standings = useMemo(() => {
    const s = {};
    for (const br of ["A", "B", "C", "D"]) s[br] = calcStandings(rrMatches[br], INITIAL_TEAMS[br]);
    return s;
  }, [rrMatches]);

  // ── Playoff team keys → actual names ──
  const playoffTeams = useMemo(() => ({
    winA: standings.A[0]?.name || null,
    runA: standings.A[1]?.name || null,
    winB: standings.B[0]?.name || null,
    runB: standings.B[1]?.name || null,
    winC: standings.C[0]?.name || null,
    runC: standings.C[1]?.name || null,
    winD: standings.D[0]?.name || null,
    runD: standings.D[1]?.name || null,
  }), [standings]);

  // Fill QF teams from group stage
  const resolvedPlayoffs = useMemo(() => {
    const p = JSON.parse(JSON.stringify(playoffs));
    for (const qf of p.qf) {
      qf.t1 = playoffTeams[qf.t1key] || `Winner ${qf.t1key.replace("win", "Bracket ").replace("run", "Runner-up ")}`;
      qf.t2 = playoffTeams[qf.t2key] || `Runner-up ${qf.t2key.replace("run", "Bracket ").replace("win", "Winner ")}`;
    }
    // SF: winners of QF1/QF2 → SF1; QF3/QF4 → SF2
    p.sf[0].t1 = getMatchWinner(p.qf[0]) || (p.qf[0].s1 !== null ? "TBD" : `Winner ${p.qf[0].label}`);
    p.sf[0].t2 = getMatchWinner(p.qf[2]) || (p.qf[2].s1 !== null ? "TBD" : `Winner ${p.qf[2].label}`);
    p.sf[1].t1 = getMatchWinner(p.qf[1]) || (p.qf[1].s1 !== null ? "TBD" : `Winner ${p.qf[1].label}`);
    p.sf[1].t2 = getMatchWinner(p.qf[3]) || (p.qf[3].s1 !== null ? "TBD" : `Winner ${p.qf[3].label}`);
    // Final: winners of SF
    p.final[0].t1 = getMatchWinner(p.sf[0]) || (p.sf[0].s1 !== null ? "TBD" : `Winner ${p.sf[0].label}`);
    p.final[0].t2 = getMatchWinner(p.sf[1]) || (p.sf[1].s1 !== null ? "TBD" : `Winner ${p.sf[1].label}`);
    return p;
  }, [playoffs, playoffTeams]);

  // ── Scorers ──
  const sortedScorers = useMemo(() =>
    Object.entries(players)
      .map(([name, d]) => ({ name, ...d }))
      .sort((a, b) => b.goals - a.goals),
    [players]);

  // ── Admin ──
  function handleLogin(e) {
    e.preventDefault();
    if (pwInput === ADMIN_PASSWORD) { setIsAdmin(true); setShowLogin(false); setPwInput(""); }
    else { alert("Wrong password"); setPwInput(""); }
  }

  // ── Score editing ──
  function startEdit(type, id) {
    setEditingMatch({ type, id });
    setScoreInputs({ s1: "", s2: "" });
  }

  function saveRRScore(br, matchId) {
    setRrMatches(prev => ({
      ...prev,
      [br]: prev[br].map(m =>
        m.id === matchId
          ? { ...m, s1: scoreInputs.s1 === "" ? null : parseInt(scoreInputs.s1), s2: scoreInputs.s2 === "" ? null : parseInt(scoreInputs.s2) }
          : m
      ),
    }));
    setEditingMatch(null);
  }

  function savePlayoffScore(round, id) {
    setPlayoffs(prev => {
      const next = JSON.parse(JSON.stringify(prev));
      const arr = next[round];
      const m = arr.find(x => x.id === id);
      if (m) {
        m.s1 = scoreInputs.s1 === "" ? null : parseInt(scoreInputs.s1);
        m.s2 = scoreInputs.s2 === "" ? null : parseInt(scoreInputs.s2);
      }
      return next;
    });
    setEditingMatch(null);
  }

  function clearScore(type, br, id) {
    if (type === "rr") {
      setRrMatches(prev => ({
        ...prev,
        [br]: prev[br].map(m => m.id === id ? { ...m, s1: null, s2: null } : m),
      }));
    } else {
      setPlayoffs(prev => {
        const next = JSON.parse(JSON.stringify(prev));
        const m = next[type].find(x => x.id === id);
        if (m) { m.s1 = null; m.s2 = null; }
        return next;
      });
    }
  }

  function addPlayer() {
    if (!newPlayer.name.trim() || !newPlayer.team.trim()) return;
    setPlayers(prev => ({
      ...prev,
      [newPlayer.name.trim()]: { team: newPlayer.team.trim(), goals: parseInt(newPlayer.goals) || 0 },
    }));
    setNewPlayer({ name: "", team: "", goals: "" });
    setShowAddPlayer(false);
  }

  function updateGoals(name, delta) {
    setPlayers(prev => ({
      ...prev,
      [name]: { ...prev[name], goals: Math.max(0, (prev[name].goals || 0) + delta) },
    }));
  }

  // ── Helpers ──
  const allTeams = Object.values(INITIAL_TEAMS).flat();
  const isEditing = (type, id) => editingMatch?.type === type && editingMatch?.id === id;

  // ─────────────────── RENDER ───────────────────────────────────────────────

  const NAV_ITEMS = [
    { id: "group", label: "Group Stage", icon: <Calendar size={16} /> },
    { id: "playoffs", label: "Playoffs", icon: <Trophy size={16} /> },
    { id: "standings", label: "Standings", icon: <Shield size={16} /> },
    { id: "scorers", label: "Top Scorers", icon: <Star size={16} /> },
  ];

  return (
    <div style={{ minHeight: "100vh", background: "#0a0a0a", color: "#fff", fontFamily: "'Barlow Condensed', 'Arial Narrow', Arial, sans-serif" }}>

      {/* ── HEADER ── */}
      <header style={{ background: "linear-gradient(180deg,#111 0%,#0a0a0a 100%)", borderBottom: "2px solid #222", position: "sticky", top: 0, zIndex: 100 }}>
        <div style={{ maxWidth: 700, margin: "0 auto", padding: "0 16px" }}>
          <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", height: 56 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
              <img src="data:image/jpeg;base64," alt="Cup of Nations" style={{ height: 44, width: "auto", flexShrink: 0 }} />
              <div>
                <div style={{ fontSize: 15, fontWeight: 800, letterSpacing: 1, lineHeight: 1, color: LIME }}>CUP OF NATIONS</div>
                <div style={{ fontSize: 11, color: "#888", letterSpacing: 2 }}>HOUSTON 2026</div>
              </div>
            </div>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              {isAdmin
                ? <button onClick={() => setIsAdmin(false)} style={btnStyle("#333", "#fff", 11)}><LogOut size={12} style={{ marginRight: 4 }} />Admin</button>
                : <button onClick={() => setShowLogin(true)} style={btnStyle("#1a1a1a", "#888", 11)}><Lock size={12} style={{ marginRight: 4 }} />Admin</button>
              }
              <button onClick={() => setMobileMenu(v => !v)} style={{ background: "none", border: "none", color: "#fff", cursor: "pointer", padding: 4, display: "flex" }}>
                {mobileMenu ? <X size={24} /> : <Menu size={24} />}
              </button>
            </div>
          </div>

          {/* mobile nav */}
          {mobileMenu && (
            <div style={{ paddingBottom: 12, display: "flex", flexDirection: "column", gap: 4 }}>
              {NAV_ITEMS.map(n => (
                <button key={n.id} onClick={() => { setTab(n.id); setMobileMenu(false); }}
                  style={{ background: tab === n.id ? LIME : "#1a1a1a", color: tab === n.id ? "#000" : "#aaa", border: "none", borderRadius: 8, padding: "10px 16px", fontWeight: 700, fontSize: 14, cursor: "pointer", display: "flex", alignItems: "center", gap: 8, textAlign: "left" }}>
                  {n.icon} {n.label}
                </button>
              ))}
            </div>
          )}

          {/* desktop nav */}
          <div style={{ display: "flex", gap: 2, paddingBottom: 0, overflowX: "auto" }}>
            {NAV_ITEMS.map(n => (
              <button key={n.id} onClick={() => { setTab(n.id); setMobileMenu(false); }}
                style={{ background: "none", border: "none", borderBottom: tab === n.id ? `3px solid ${LIME}` : "3px solid transparent", color: tab === n.id ? LIME : "#666", fontWeight: 700, fontSize: 13, padding: "10px 14px", cursor: "pointer", whiteSpace: "nowrap", letterSpacing: 0.5, display: "flex", alignItems: "center", gap: 6 }}>
                {n.icon} {n.label.toUpperCase()}
              </button>
            ))}
          </div>
        </div>
      </header>

      {/* ── LOGIN MODAL ── */}
      {showLogin && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,.85)", zIndex: 999, display: "flex", alignItems: "center", justifyContent: "center", padding: 16 }}>
          <div style={{ background: "#111", border: "1px solid #333", borderRadius: 16, padding: 32, width: "100%", maxWidth: 340 }}>
            <div style={{ fontSize: 20, fontWeight: 800, marginBottom: 20, color: LIME }}>Admin Login</div>
            <form onSubmit={handleLogin}>
              <input type="password" value={pwInput} onChange={e => setPwInput(e.target.value)}
                placeholder="Password" autoFocus
                style={{ width: "100%", background: "#1a1a1a", border: "1px solid #333", borderRadius: 8, padding: "12px 14px", color: "#fff", fontSize: 15, boxSizing: "border-box", marginBottom: 12 }} />
              <div style={{ display: "flex", gap: 8 }}>
                <button type="submit" style={{ ...btnStyle(LIME, "#000", 14), flex: 1, padding: "12px 0", fontWeight: 800 }}>Login</button>
                <button type="button" onClick={() => setShowLogin(false)} style={{ ...btnStyle("#222", "#aaa", 14), flex: 1, padding: "12px 0" }}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}

      <div style={{ maxWidth: 700, margin: "0 auto", padding: "16px 12px 80px" }}>

        {/* ══════════════ GROUP STAGE ══════════════ */}
        {tab === "group" && (
          <div>
            <SectionHeader icon={<Calendar size={18} />} title="Group Stage" sub="Day 1 · Round Robin" />
            {["A", "B", "C", "D"].map(br => (
              <div key={br} style={{ marginBottom: 12 }}>
                <button onClick={() => setExpandedBracket(expandedBracket === br ? null : br)}
                  style={{ width: "100%", background: "#141414", border: "1px solid #2a2a2a", borderRadius: expandedBracket === br ? "12px 12px 0 0" : 12, padding: "12px 16px", display: "flex", alignItems: "center", justifyContent: "space-between", cursor: "pointer", color: "#fff" }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                    <div style={{ width: 28, height: 28, borderRadius: 6, background: LIME, color: "#000", fontWeight: 900, fontSize: 15, display: "flex", alignItems: "center", justifyContent: "center" }}>{br}</div>
                    <span style={{ fontWeight: 700, fontSize: 15 }}>Bracket {br}</span>
                    <span style={{ color: "#555", fontSize: 12 }}>{INITIAL_TEAMS[br].join(" · ")}</span>
                  </div>
                  {expandedBracket === br ? <ChevronUp size={18} color="#666" /> : <ChevronDown size={18} color="#666" />}
                </button>

                {expandedBracket === br && (
                  <div style={{ background: "#0f0f0f", border: "1px solid #2a2a2a", borderTop: "none", borderRadius: "0 0 12px 12px", overflow: "hidden" }}>
                    {rrMatches[br].map(m => (
                      <MatchRow
                        key={m.id}
                        match={m}
                        isAdmin={isAdmin}
                        isEditing={isEditing("rr-" + br, m.id)}
                        scoreInputs={scoreInputs}
                        onEdit={() => startEdit("rr-" + br, m.id)}
                        onSave={() => saveRRScore(br, m.id)}
                        onClear={() => clearScore("rr", br, m.id)}
                        onCancel={() => setEditingMatch(null)}
                        onScoreChange={setScoreInputs}
                      />
                    ))}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}

        {/* ══════════════ PLAYOFFS ══════════════ */}
        {tab === "playoffs" && (
          <div>
            <SectionHeader icon={<Trophy size={18} />} title="Playoffs" sub="Day 2 · Quarterfinals → Semifinals → Final" />

            {/* BREAK badge helper */}
            {/* QF */}
            <RoundBlock title="Quarter-Finals" time="8:00 – 9:00 AM">
              {resolvedPlayoffs.qf.map(m => (
                <MatchRow key={m.id} match={m} isAdmin={isAdmin}
                  isEditing={isEditing("qf", m.id)}
                  scoreInputs={scoreInputs}
                  onEdit={() => startEdit("qf", m.id)}
                  onSave={() => savePlayoffScore("qf", m.id)}
                  onClear={() => clearScore("qf", null, m.id)}
                  onCancel={() => setEditingMatch(null)}
                  onScoreChange={setScoreInputs}
                  showLabel showField />
              ))}
            </RoundBlock>

            <BreakBadge time="10:00 AM" />

            {/* SF */}
            <RoundBlock title="Semi-Finals" time="10:30 AM">
              {resolvedPlayoffs.sf.map(m => (
                <MatchRow key={m.id} match={m} isAdmin={isAdmin}
                  isEditing={isEditing("sf", m.id)}
                  scoreInputs={scoreInputs}
                  onEdit={() => startEdit("sf", m.id)}
                  onSave={() => savePlayoffScore("sf", m.id)}
                  onClear={() => clearScore("sf", null, m.id)}
                  onCancel={() => setEditingMatch(null)}
                  onScoreChange={setScoreInputs}
                  showLabel showField />
              ))}
            </RoundBlock>

            <BreakBadge time="11:30 AM" />

            {/* FINAL */}
            <RoundBlock title="⚽ Final" time="12:00 PM" highlight>
              {resolvedPlayoffs.final.map(m => (
                <MatchRow key={m.id} match={m} isAdmin={isAdmin}
                  isEditing={isEditing("final", m.id)}
                  scoreInputs={scoreInputs}
                  onEdit={() => startEdit("final", m.id)}
                  onSave={() => savePlayoffScore("final", m.id)}
                  onClear={() => clearScore("final", null, m.id)}
                  onCancel={() => setEditingMatch(null)}
                  onScoreChange={setScoreInputs}
                  showField isFinal />
              ))}
            </RoundBlock>

            {/* Closing */}
            <div style={{ marginTop: 12, background: `linear-gradient(135deg,${GOLD}22,${GOLD}11)`, border: `1px solid ${GOLD}44`, borderRadius: 12, padding: "16px 20px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <div>
                <div style={{ color: GOLD, fontWeight: 800, fontSize: 16, letterSpacing: 1 }}>🏆 CLOSING CEREMONY</div>
                <div style={{ color: "#888", fontSize: 12, marginTop: 2 }}>1:00 PM</div>
              </div>
              <Trophy size={28} color={GOLD} />
            </div>

            {/* Champion display */}
            {(() => {
              const champ = getMatchWinner(resolvedPlayoffs.final[0]);
              if (!champ) return null;
              return (
                <div style={{ marginTop: 16, background: `linear-gradient(135deg,${GOLD}33,${GOLD}11)`, border: `2px solid ${GOLD}`, borderRadius: 16, padding: 24, textAlign: "center" }}>
                  <div style={{ fontSize: 13, color: GOLD, letterSpacing: 3, marginBottom: 6 }}>🏆 CHAMPION</div>
                  <div style={{ fontSize: 32, fontWeight: 900, color: "#fff", letterSpacing: 2 }}>{champ}</div>
                  <div style={{ fontSize: 11, color: "#888", marginTop: 6, letterSpacing: 2 }}>ONE NATION · ONE CUP · ONE CHAMPION</div>
                </div>
              );
            })()}
          </div>
        )}

        {/* ══════════════ STANDINGS ══════════════ */}
        {tab === "standings" && (
          <div>
            <SectionHeader icon={<Shield size={18} />} title="Standings" sub="Group stage rankings" />
            {["A", "B", "C", "D"].map(br => (
              <div key={br} style={{ marginBottom: 16, background: "#0f0f0f", border: "1px solid #1e1e1e", borderRadius: 14, overflow: "hidden" }}>
                <div style={{ background: "#141414", padding: "10px 16px", display: "flex", alignItems: "center", gap: 10, borderBottom: "1px solid #1e1e1e" }}>
                  <div style={{ width: 26, height: 26, borderRadius: 6, background: LIME, color: "#000", fontWeight: 900, fontSize: 14, display: "flex", alignItems: "center", justifyContent: "center" }}>{br}</div>
                  <span style={{ fontWeight: 800, fontSize: 14 }}>Bracket {br}</span>
                </div>
                {/* header */}
                <div style={{ display: "grid", gridTemplateColumns: "1fr 36px 36px 36px 52px 36px", gap: 0, padding: "8px 16px", borderBottom: "1px solid #1a1a1a" }}>
                  {["TEAM", "W", "D", "L", "GF-GA", "PTS"].map(h => (
                    <div key={h} style={{ fontSize: 10, color: "#555", fontWeight: 700, textAlign: h === "TEAM" ? "left" : "center", letterSpacing: 0.5 }}>{h}</div>
                  ))}
                </div>
                {standings[br].map((t, i) => (
                  <div key={t.name} style={{ display: "grid", gridTemplateColumns: "1fr 36px 36px 36px 52px 36px", gap: 0, padding: "10px 16px", borderBottom: i < 3 ? "1px solid #161616" : "none", background: i === 0 ? `${LIME}08` : i === 1 ? `${LIME}04` : "transparent" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                      <span style={{ color: i < 2 ? LIME : "#555", fontWeight: 700, fontSize: 12, width: 14 }}>{i + 1}</span>
                      <span style={{ fontSize: 14, fontWeight: i < 2 ? 700 : 400, color: i < 2 ? "#fff" : "#aaa" }}>{t.name}</span>
                      {i < 2 && <span style={{ fontSize: 9, background: LIME, color: "#000", borderRadius: 3, padding: "1px 4px", fontWeight: 800 }}>ADV</span>}
                    </div>
                    {[t.w, t.d, t.l].map((v, vi) => <div key={vi} style={{ textAlign: "center", fontSize: 13, color: "#ccc" }}>{v}</div>)}
                    <div style={{ textAlign: "center", fontSize: 12, color: "#888" }}>{t.gf}-{t.ga}</div>
                    <div style={{ textAlign: "center", fontSize: 14, fontWeight: 800, color: LIME }}>{t.pts}</div>
                  </div>
                ))}
              </div>
            ))}
          </div>
        )}

        {/* ══════════════ TOP SCORERS ══════════════ */}
        {tab === "scorers" && (
          <div>
            <SectionHeader icon={<Star size={18} />} title="Top Scorers" sub="Live goal tracker" />

            {isAdmin && (
              <div style={{ marginBottom: 16 }}>
                {!showAddPlayer
                  ? <button onClick={() => setShowAddPlayer(true)} style={{ ...btnStyle(LIME, "#000", 13), width: "100%", padding: "12px 0", fontWeight: 800 }}>+ Add Player</button>
                  : (
                    <div style={{ background: "#111", border: "1px solid #2a2a2a", borderRadius: 12, padding: 16 }}>
                      <div style={{ fontSize: 13, fontWeight: 700, marginBottom: 12, color: LIME }}>Add New Player</div>
                      <input placeholder="Player name" value={newPlayer.name} onChange={e => setNewPlayer(p => ({ ...p, name: e.target.value }))}
                        style={inputStyle} />
                      <select value={newPlayer.team} onChange={e => setNewPlayer(p => ({ ...p, team: e.target.value }))}
                        style={{ ...inputStyle, marginTop: 8 }}>
                        <option value="">Select team…</option>
                        {allTeams.map(t => <option key={t} value={t}>{t}</option>)}
                      </select>
                      <input type="number" placeholder="Goals (default 0)" value={newPlayer.goals} onChange={e => setNewPlayer(p => ({ ...p, goals: e.target.value }))}
                        style={{ ...inputStyle, marginTop: 8 }} />
                      <div style={{ display: "flex", gap: 8, marginTop: 10 }}>
                        <button onClick={addPlayer} style={{ ...btnStyle(LIME, "#000", 13), flex: 1, padding: "10px 0", fontWeight: 800 }}>Save</button>
                        <button onClick={() => setShowAddPlayer(false)} style={{ ...btnStyle("#222", "#aaa", 13), flex: 1, padding: "10px 0" }}>Cancel</button>
                      </div>
                    </div>
                  )}
              </div>
            )}

            {sortedScorers.length === 0
              ? <div style={{ textAlign: "center", padding: 48, color: "#444", fontSize: 14 }}>No players added yet.</div>
              : (
                <div style={{ background: "#0f0f0f", border: "1px solid #1e1e1e", borderRadius: 14, overflow: "hidden" }}>
                  {sortedScorers.map((p, i) => (
                    <div key={p.name} style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", borderBottom: i < sortedScorers.length - 1 ? "1px solid #161616" : "none", background: i === 0 ? `${GOLD}0a` : "transparent" }}>
                      <div style={{ width: 28, textAlign: "center", fontSize: 16, fontWeight: 900, color: i === 0 ? GOLD : i === 1 ? "#aaa" : i === 2 ? "#cd7f32" : "#444" }}>
                        {i === 0 ? "🥇" : i === 1 ? "🥈" : i === 2 ? "🥉" : i + 1}
                      </div>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontWeight: 700, fontSize: 15 }}>{p.name}</div>
                        <div style={{ fontSize: 11, color: "#666" }}>{p.team}</div>
                      </div>
                      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                        {isAdmin && (
                          <>
                            <button onClick={() => updateGoals(p.name, -1)} style={{ ...btnStyle("#1a1a1a", "#fff", 16), width: 30, height: 30, padding: 0, borderRadius: 6 }}>−</button>
                          </>
                        )}
                        <div style={{ minWidth: 36, textAlign: "center" }}>
                          <div style={{ fontSize: 24, fontWeight: 900, color: LIME, lineHeight: 1 }}>{p.goals}</div>
                          <div style={{ fontSize: 9, color: "#555", letterSpacing: 1 }}>GOALS</div>
                        </div>
                        {isAdmin && (
                          <button onClick={() => updateGoals(p.name, 1)} style={{ ...btnStyle(LIME, "#000", 16), width: 30, height: 30, padding: 0, borderRadius: 6, fontWeight: 900 }}>+</button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              )}
          </div>
        )}
      </div>
    </div>
  );
}

// ─── SUB-COMPONENTS ───────────────────────────────────────────────────────────

function SectionHeader({ icon, title, sub }) {
  return (
    <div style={{ marginBottom: 16 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <span style={{ color: "#BFFF00" }}>{icon}</span>
        <h2 style={{ fontSize: 22, fontWeight: 900, letterSpacing: 1, margin: 0 }}>{title}</h2>
      </div>
      {sub && <div style={{ fontSize: 12, color: "#555", marginTop: 2, letterSpacing: 1 }}>{sub.toUpperCase()}</div>}
    </div>
  );
}

function RoundBlock({ title, time, children, highlight }) {
  const LIME = "#BFFF00";
  return (
    <div style={{ marginBottom: 12 }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "8px 16px 8px", background: highlight ? `linear-gradient(90deg,${LIME}22,transparent)` : "#141414", borderRadius: "12px 12px 0 0", border: `1px solid ${highlight ? LIME + "44" : "#2a2a2a"}`, borderBottom: "none" }}>
        <span style={{ fontWeight: 800, fontSize: 14, color: highlight ? LIME : "#fff", letterSpacing: 0.5 }}>{title.toUpperCase()}</span>
        <span style={{ fontSize: 11, color: "#666" }}>{time}</span>
      </div>
      <div style={{ background: "#0f0f0f", border: `1px solid ${highlight ? LIME + "44" : "#2a2a2a"}`, borderTop: "none", borderRadius: "0 0 12px 12px", overflow: "hidden" }}>
        {children}
      </div>
    </div>
  );
}

function BreakBadge({ time }) {
  const GOLD = "#FFD700";
  return (
    <div style={{ margin: "8px 0", background: `${GOLD}11`, border: `1px dashed ${GOLD}33`, borderRadius: 8, padding: "8px 16px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
      <span style={{ color: GOLD, fontSize: 12, fontWeight: 700, letterSpacing: 2 }}>☕ BREAK</span>
      <span style={{ color: "#666", fontSize: 11 }}>{time}</span>
    </div>
  );
}

function MatchRow({ match, isAdmin, isEditing, scoreInputs, onEdit, onSave, onClear, onCancel, onScoreChange, showLabel, showField, isFinal }) {
  const LIME = "#BFFF00";
  const hasScore = match.s1 !== null && match.s2 !== null;
  const s1 = parseInt(match.s1), s2 = parseInt(match.s2);
  const t1wins = hasScore && s1 > s2, t2wins = hasScore && s2 > s1;

  return (
    <div style={{ borderBottom: "1px solid #161616", padding: "10px 14px", background: isFinal ? `${LIME}05` : "transparent" }}>
      {/* meta row */}
      {(showLabel || showField || match.time) && (
        <div style={{ display: "flex", gap: 10, marginBottom: 6 }}>
          {showLabel && match.label && <span style={{ fontSize: 10, color: "#666", fontWeight: 700, letterSpacing: 0.5 }}>{match.label.toUpperCase()}</span>}
          {match.time && <span style={{ fontSize: 10, color: "#555" }}>{match.time}</span>}
          {showField && match.field && <span style={{ fontSize: 10, color: "#555" }}>{match.field}</span>}
        </div>
      )}

      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        {/* Team 1 */}
        <div style={{ flex: 1, fontWeight: t1wins ? 800 : 400, color: t1wins ? "#fff" : t2wins ? "#555" : "#ccc", fontSize: 14, textAlign: "right" }}>
          {match.t1 || "—"}
        </div>

        {/* Score */}
        <div style={{ flexShrink: 0, minWidth: 72, textAlign: "center" }}>
          {isEditing ? (
            <div style={{ display: "flex", alignItems: "center", gap: 4 }}>
              <input type="number" min="0" value={scoreInputs.s1} onChange={e => onScoreChange(p => ({ ...p, s1: e.target.value }))}
                style={{ width: 36, background: "#1a1a1a", border: `1px solid ${LIME}`, borderRadius: 6, color: "#fff", fontSize: 16, fontWeight: 700, textAlign: "center", padding: "4px 0" }} />
              <span style={{ color: "#555" }}>:</span>
              <input type="number" min="0" value={scoreInputs.s2} onChange={e => onScoreChange(p => ({ ...p, s2: e.target.value }))}
                style={{ width: 36, background: "#1a1a1a", border: `1px solid ${LIME}`, borderRadius: 6, color: "#fff", fontSize: 16, fontWeight: 700, textAlign: "center", padding: "4px 0" }} />
            </div>
          ) : hasScore ? (
            <span style={{ fontSize: 18, fontWeight: 900, color: "#fff", letterSpacing: 2 }}>{match.s1} : {match.s2}</span>
          ) : (
            <span style={{ fontSize: 13, color: "#333", letterSpacing: 3 }}>— : —</span>
          )}
        </div>

        {/* Team 2 */}
        <div style={{ flex: 1, fontWeight: t2wins ? 800 : 400, color: t2wins ? "#fff" : t1wins ? "#555" : "#ccc", fontSize: 14 }}>
          {match.t2 || "—"}
        </div>

        {/* Admin controls */}
        {isAdmin && (
          <div style={{ flexShrink: 0, display: "flex", gap: 4 }}>
            {isEditing ? (
              <>
                <button onClick={onSave} style={{ ...btnStyle(LIME, "#000", 11), padding: "5px 10px", fontWeight: 800 }}>✓</button>
                <button onClick={onCancel} style={{ ...btnStyle("#222", "#aaa", 11), padding: "5px 10px" }}>✕</button>
              </>
            ) : (
              <>
                <button onClick={onEdit} style={{ ...btnStyle("#1a1a1a", "#aaa", 11), padding: "5px 10px" }}>Edit</button>
                {hasScore && <button onClick={onClear} style={{ ...btnStyle("#1a1a1a", "#555", 11), padding: "5px 10px" }}>×</button>}
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// ─── UTILS ────────────────────────────────────────────────────────────────────
function btnStyle(bg, color, fs = 13) {
  return { background: bg, color, border: "none", borderRadius: 8, padding: "6px 12px", fontSize: fs, cursor: "pointer", display: "inline-flex", alignItems: "center", justifyContent: "center" };
}
const inputStyle = { display: "block", width: "100%", background: "#1a1a1a", border: "1px solid #333", borderRadius: 8, padding: "10px 12px", color: "#fff", fontSize: 14, boxSizing: "border-box" };
